//! Monsters and NPCs: the appearance of each monster number the server sends.
//!
//! This is what `CreateMonster(Type, x, y, Key)` does (ZzzCharacter.cpp:12577 in Main 5.2): first the
//! per-map creators (Cursed Temple, Hellas, Battle Castle, Crywolf, Aida, Kanturu, Elbeland,
//! Raklion...), then the big `switch(Type)`, and finally `Setting_Monster` (Blood Castle scale and kind).
//! The table ([`table`]) is generated by `tools/gen_monsters.py` walking that code; here are the types,
//! the lookup and what the original computes separately:
//! - [`Def`]: model, scale, weapons (only the item type and level: drawing them is the items' job),
//!   `Level`, `BlendMesh`, `HiddenMesh`...
//! - [`MonsterModel`]: each action's `PlaySpeed` and `Loop` from `OpenMonsterModel` (ZzzOpenData.cpp:2367).
//! - [`NpcModel`]: file and `PlaySpeed` of the `OpenNpc` models (ZzzOpenData.cpp:1865).
//!
//! The names the original reads (`NpcName_<language>.txt`, `OpenMonsterScript`) are not in our Data:
//! they come from MuMain's `Monsters/Monsters.json` (in Spanish when available).

mod table;

pub use table::{DEFAULT_DEF, DEFS, MONSTER_MODELS, MONSTER_WAVES, NPC_MODELS, OTHER_LINK_BONES};

/// Monster and NPC model actions (`MONSTER01_*`, _define.h:483-494).
pub mod action {
    pub const STOP1: usize = 0;
    pub const STOP2: usize = 1;
    pub const WALK: usize = 2;
    pub const ATTACK1: usize = 3;
    pub const ATTACK2: usize = 4;
    pub const SHOCK: usize = 5;
    pub const DIE: usize = 6;
    pub const APEAR: usize = 7;
    pub const ATTACK3: usize = 8;
    pub const ATTACK4: usize = 9;
    pub const RUN: usize = 10;
    pub const ATTACK5: usize = 11;
    /// Those with their own `PlaySpeed` in the tables.
    pub const COUNT: usize = 12;
}

/// An item (weapon, armor piece...): the original's `MODEL_<group> + index`, with its level.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Item {
    /// 0 swords, 1 axes, 2 maces, 3 spears, 4 bows, 5 staffs, 6 shields, 7 helms, 8 armors,
    /// 9 pants, 10 gloves, 11 boots, 12 wings, 13 helpers...
    pub group: u8,
    pub index: u16,
    pub level: u8,
    /// `Option1` (excellent).
    pub option: u8,
}

/// Body part (`c->BodyPart[...]`) for those using the player skeleton or the merchants.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Part {
    None,
    /// A player armor piece (`MODEL_HELM + n`...).
    Item(Item),
    /// A merchant piece (`MODEL_MERCHANT_MAN_HEAD`...): see [`NpcModel::parts`].
    Npc(&'static str),
}

/// Which model is drawn.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Model {
    /// `MODEL_MONSTER01 + n`: `Data/Monster/Monster{n+1:02}.bmd`.
    Monster(u16),
    /// An `OpenNpc` model (the `MODEL_*` name): [`npc_model`].
    Npc(&'static str),
    /// `MODEL_PLAYER`: the `player.bmd` skeleton with [`Def::sub_type`] (skeletons) or [`Def::body`].
    Player,
    /// `CreateCharacter(Key, n, ...)`: the model of map object `n` (traps).
    Object(u16),
    /// Another global model (`MODEL_WARCRAFT`, `MODEL_BALL`): [`other_model`].
    Other(&'static str),
}

/// `o->SubType`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SubType {
    Value(i32),
    /// A model (`MODEL_SKELETON1`...): what is drawn over the player skeleton.
    Model(&'static str),
}

/// `o->Kind` (`KIND_*`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Monster,
    Npc,
    Trap,
    /// `KIND_TMP` (number 451).
    Tmp,
}

/// The appearance of a monster number, as `CreateMonster` leaves it (anything it does not set keeps
/// the `CreateCharacterPointer` value, ZzzCharacter.cpp:11263: [`BASE`]).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Def {
    pub number: u16,
    /// Maps (`WorldActive`) where this entry applies; empty = all others.
    pub maps: &'static [u8],
    pub model: Model,
    pub scale: f32,
    /// `c->Weapon[0..2]` (right hand, left hand).
    pub weapons: [Option<Item>; 2],
    /// `c->BodyPart[HELM, ARMOR, PANTS, GLOVES, BOOTS]`.
    pub body: [Part; 5],
    pub wing: Option<Item>,
    pub helper: Option<Item>,
    /// `c->Level`: monsters with a level glow differently (`RenderCharacter`).
    pub level: u8,
    /// `o->HiddenMesh` (-1 = none).
    pub hidden_mesh: i16,
    /// `o->BlendMesh` (-1 = none).
    pub blend_mesh: i16,
    pub blend_mesh_light: f32,
    /// `c->m_bFixForm`: whirlwinds do not spin it (`StormTime`, ZzzEffect.cpp:149).
    pub fix_form: bool,
    pub hide_shadow: bool,
    /// `o->m_bRenderShadow`.
    pub render_shadow: bool,
    /// `c->Blood`: already shed its blood (does not on death).
    pub blood: bool,
    pub sub_type: SubType,
    /// `o->Kind` set by hand in the `case` (otherwise [`kind`]).
    pub kind: Option<Kind>,
    pub alpha_target: f32,
    /// `c->MoveSpeed`: MU units per tick (100 = one tile).
    pub move_speed: u8,
    pub edge_scale: f32,
    pub visible: bool,
    pub live: bool,
    pub light_enable: bool,
    pub pc_room: bool,
    pub life_time: Option<i32>,
    /// `c->Class` (the character-shaped Doppelganger ones).
    pub class: Option<&'static str>,
    pub skin: u8,
    /// `SetAction` on creation.
    pub start_action: Option<u16>,
    /// `o->CurrentAction = PLAYER_*` (character-shaped NPCs).
    pub start_player_action: Option<&'static str>,
    /// `o->AnimationFrame` on creation.
    pub start_frame: Option<f32>,
    /// Height above the ground (`Position[2] = RequestTerrainHeight(...) + h`).
    pub height: Option<f32>,
    /// `Position[2] += z`.
    pub z_offset: f32,
    /// `Angle[i] = ...`.
    pub angle: [Option<f32>; 3],
    /// Rotation from `CreateCharacter(..., Rotation)`.
    pub rotation: Option<f32>,
    /// Tile offset in `CreateCharacter(Key, Type, x + dx, y + dy)`.
    pub tile_offset: (i8, i8),
    pub bbox_max: Option<[f32; 3]>,
    /// `Models[...].Actions[i].PlaySpeed = v` in the `case` (changes the model for everyone).
    pub model_speeds: &'static [(u8, f32)],
    /// `Models[...].Meshs[i].NoneBlendMesh`.
    pub none_blend: &'static [(u8, bool)],
    /// `Models[...].StreamMesh`.
    pub stream_mesh: Option<i16>,
    /// Parts of the `case` not ported yet (effects, named bones...), with their file:line.
    pub notes: &'static [&'static str],
    /// File:line of the `case`.
    pub src: &'static str,
    /// Maps (`WorldActive`) where it appears, per MuMain's `Monsters.json` (not from the original:
    /// only for picking test monsters).
    pub seen_in: &'static [u8],
    pub name: &'static str,
    /// English name if different.
    pub name_en: &'static str,
}

